import {
  Card,
  CardContent,
  CardHeader,
  Checkbox,
  CheckboxGroup,
  CheckboxGroupProps,
  CheckboxGroupItem,
  CheckboxGroupItemProps,
  Divider,
  Heading,
  Input,
  Textarea,
  useToast,
} from '@/components/ui'
import { useMutation } from '@tanstack/react-query'
import { useForm } from 'react-hook-form'
import { zodResolver } from '@hookform/resolvers/zod'
import { z } from 'zod'
import { useRouter } from 'next/navigation'
import { useEffect, useState } from 'react'

export default function Inventory() {
  const router = useRouter()

  const [search, setSearch] = useState('')
  const [state, setState] = useState({
    items: [],
    error: null,
  })

  const { data, isLoading, refetch } = useInventory()
  const { mutate: add } = useMutation({
    mutationFn: (item: z.infer<typeof itemSchema>) => {
      return prisma.item.create({ data: item })
    },
    onSuccess: () => {
      setState((s) => ({ ...s, items: [...s.items, s.items[0]] }))
      refetch()
    },
    onError: () => {
      setState((s) => ({ ...s, error: 'Failed to add item' }))
    },
  })

  const items = data?.map((i) => i.name) || []

  const itemSchema = z.object({
    name: z.string(),
    stock: z.number(),
    id: z.string(),
    image: z.string(),
  })

  const form = useForm<z.infer<typeof itemSchema>>({
    resolver: zodResolver(itemSchema),
    defaultValues: {
      name: '',
      stock: 0,
      id: '',
      image: '',
    },
  })

  const { register, handleSubmit, formState: { errors } } = form

  const handleAdd = (e: React.ChangeEvent<HTMLInputElement>) => {
    e.preventDefault()
    add({
      name: e.target.value,
    })
    setSearch(e.target.value)
  }

  const handleSearch = (e: React.ChangeEvent<HTMLInputElement>) => {
    setSearch(e.target.value)
  }

  useEffect(() => {
    if (search) {
      setState((s) => ({
        ...s,
        items: data?.filter((i) =>
          i.name.toLowerCase().includes(search.toLowerCase())
        ),
      }))
    }
  }, [data, search])

  return (
    <>
      <div className="grid grid-cols-2 gap-3 sm:grid-cols-4">
        <Card>
          <CardHeader className="flex flex-col justify-center items-center">
            <Heading as="h2">Search</Heading>
            <Input
              placeholder="Search"
              value={search}
              onChange={handleSearch}
            />
          </CardHeader>
          <CardContent className="p-4">
            {state.error && (
              <div className="text-2xl font-semibold tabular-nums">
                {state.error}
              </div>
            )}
            <Divider />
            {state.items.map((i) => (
              <CheckboxGroupItem
                key={i.id}
                id={i.id}
                value={i.id}
                label={i.name}
                group="items"
                register={register}
                errors={errors}
